SELECT 
FROM TBL_TREASURY_BUSINESS_TYPES


        AND ORGID = #{orgId}


        AND TYPECODE LIKE CONCAT('%', #{typeCode}, '%')


        AND TYPENAME LIKE CONCAT('%', #{typeName}, '%')


        AND PARENTTYPEID = #{parentTypeId}


        AND ISENABLED = #{isEnabled}


ORDER BY TYPELEVEL ASC, SORTORDER ASC, CREATETIME DESC

SELECT 
FROM TBL_TREASURY_BUSINESS_TYPES
WHERE TYPECODE = #{typeCode} AND ORGID = #{orgId}

SELECT COUNT(1)
FROM TBL_TREASURY_BUSINESS_TYPES
WHERE TYPECODE = #{typeCode} AND ORGID = #{orgId}

    AND BUSINESSTYPEID != #{excludeId}
